import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"04-task-chat-vault — Task Workflow, Realtime Workspace Chat, Reference Hub & Encrypted S3 Vault (4 Modules)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/04-task-chat-vault/README.md","filePath":"feature/modules/04-task-chat-vault/README.md"}'),l={name:"feature/modules/04-task-chat-vault/README.md"};function c(s,e,d,n,i,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_04-task-chat-vault-—-task-workflow-realtime-workspace-chat-reference-hub-encrypted-s3-vault-4-modules" tabindex="-1">04-task-chat-vault — Task Workflow, Realtime Workspace Chat, Reference Hub &amp; Encrypted S3 Vault (4 Modules) <a class="header-anchor" href="#_04-task-chat-vault-—-task-workflow-realtime-workspace-chat-reference-hub-encrypted-s3-vault-4-modules" aria-label="Permalink to &quot;04-task-chat-vault — Task Workflow, Realtime Workspace Chat, Reference Hub &amp; Encrypted S3 Vault (4 Modules)&quot;">​</a></h1><p>&gt; <strong>Navigation:</strong> <a href="./../../README.html">← Feature Master Index</a> · <a href="./../README.html">← Modules Master Index</a> · <a href="./../../srs/05-content-task-workflow/README.html">SRS 3.6 Content &amp; Workflow</a> · <a href="./../../../ba/05-content-task-workflow.html">BA Domain Spec</a> · <a href="./../../../rule/feature-workflow.html">Workflow Rule</a></p><p>Core daily collaboration and asset security architecture uniting the 5-state inline Task workflow, multi-channel STOMP Workspace Chat with 1:1 Agora RTC voice calls, and KMS AES-256-GCM envelope-encrypted S3 Material Vaults with Google Drive import.</p><hr><h2 id="_1-production-codebase-persistence-mapping" tabindex="-1">1. Production Codebase &amp; Persistence Mapping <a class="header-anchor" href="#_1-production-codebase-persistence-mapping" aria-label="Permalink to &quot;1. Production Codebase &amp; Persistence Mapping&quot;">​</a></h2><ul><li><strong>Primary Services:</strong> <code>brandhub-business-service</code> (<code>TaskController</code>, <code>TaskWorkflowController</code>, <code>TaskSectionController</code>, <code>ChatChannelController</code>, <code>ChatMessageController</code>, <code>ChatCallController</code>, <code>MaterialController</code>, <code>MaterialFolderController</code>, <code>RepositoryEnvelopeCrypto</code>, <code>ClientVaultController</code>, <code>DriveFolderImportController</code>, <code>CustomerDriveController</code>) and <code>brandhub-web</code>.</li><li><strong>Storage &amp; Runtime State:</strong><ul><li><strong>PostgreSQL 17:</strong> <code>storage_addon_packages</code>, <code>agency_storage_addons</code>, <code>client_vault_folders</code>, <code>client_vault_shares</code>, <code>workspace_hashtags</code>.</li><li><strong>MongoDB 7.0:</strong> <code>tasks</code>, <code>task_versions</code>, <code>materials</code>, <code>material_folders</code>, <code>chat_channels</code>, <code>chat_messages</code>, <code>chat_threads</code>, <code>scheduled_chat_messages</code>.</li><li><strong>AWS S3 + KMS:</strong> Envelope-encrypted repository blobs served via short-lived capability URLs (<code>/api/v1/repository-media/*</code>) so <code>Admin</code> / Dev operators cannot inspect raw tenant media.</li></ul></li><li><strong>Related Canonical SRS Domain:</strong> <a href="./../../srs/05-content-task-workflow/README.html">05-content-task-workflow (<code>3.6.1</code>–<code>3.6.35</code>)</a>.</li></ul><hr><h2 id="_2-consolidated-modules-4" tabindex="-1">2. Consolidated Modules (<code>4</code>) <a class="header-anchor" href="#_2-consolidated-modules-4" aria-label="Permalink to &quot;2. Consolidated Modules (`4`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Module Slug</th><th style="text-align:left;">Scope &amp; Engineering Title</th><th style="text-align:left;">Core Codebase Touchpoints</th><th style="text-align:left;">Lifecycle Artefacts (<code>spec → plan → task → test</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>task-subtask-and-inline-workflow</code></td><td style="text-align:left;"><strong>Five-State Inline Task Editing, Role-Scoped Subtasks &amp; Sectioned Specialized Editors</strong></td><td style="text-align:left;"><code>TODO -&gt; IN_PROGRESS -&gt; INTERNAL_REVIEW -&gt; CLIENT_REVIEW -&gt; APPROVED</code> workflow, role-locked subtasks, specialized Post/Survey/Video task sections</td><td style="text-align:left;"><a href="./task-subtask-and-inline-workflow/spec.html">Spec</a> · <a href="./task-subtask-and-inline-workflow/plan.html">Plan</a> · <a href="./task-subtask-and-inline-workflow/task.html">Task</a> · <a href="./task-subtask-and-inline-workflow/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>reference-hub-and-algorithmic-curation</code></td><td style="text-align:left;"><strong>Smart Reference Hub, Shared Moodboard &amp; Client-Side Algorithmic Curation Engine</strong></td><td style="text-align:left;"><code>WorkspaceReferenceController</code>, MongoDB <code>workspace_moodboard_items</code>, <code>ReferencePreviewModal</code> (TextRank), Content Kit Tripartite Pairing, Facet Clustering, CIELAB $\\Delta E$ Color Harmony, Storyboard B-roll Assigner &amp; Session Rocchio + MMR</td><td style="text-align:left;"><a href="./reference-hub-and-algorithmic-curation/spec.html">Spec</a> · <a href="./reference-hub-and-algorithmic-curation/plan.html">Plan</a> · <a href="./reference-hub-and-algorithmic-curation/task.html">Task</a> · <a href="./reference-hub-and-algorithmic-curation/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>workspace-chat-and-voice-calls</code></td><td style="text-align:left;"><strong>Workspace Realtime Chat Channels, Threads, Mentions, Slash References, Scheduled Messages &amp; 1:1 Voice Calls</strong></td><td style="text-align:left;">STOMP <code>/ws/chat</code>, <code>PUBLIC</code> / <code>PRIVATE</code> / <code>DIRECT</code> channels, <code>/task</code> &amp; <code>/material</code> rich cards, <code>@mentions</code> inbox, DND mute, <code>ChatCallController</code> 1:1 voice</td><td style="text-align:left;"><a href="./workspace-chat-and-voice-calls/spec.html">Spec</a> · <a href="./workspace-chat-and-voice-calls/plan.html">Plan</a> · <a href="./workspace-chat-and-voice-calls/task.html">Task</a> · <a href="./workspace-chat-and-voice-calls/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>s3-folder-vault-security</code></td><td style="text-align:left;"><strong>Encrypted S3 Material Repository, Storage Add-Ons, Client Folder Vault &amp; Google Drive Sync</strong></td><td style="text-align:left;"><code>RepositoryEnvelopeCrypto</code> (<code>AES-256-GCM</code>), 5 GB free + add-on quota (<code>StorageQuotaService</code>), <code>Client</code> cross-workspace Vault share, Google Drive tree import</td><td style="text-align:left;"><a href="./s3-folder-vault-security/spec.html">Spec</a> · <a href="./s3-folder-vault-security/plan.html">Plan</a> · <a href="./s3-folder-vault-security/task.html">Task</a> · <a href="./s3-folder-vault-security/test.html">Test</a></td></tr></tbody></table><hr><h2 id="_3-security-collaboration-invariants" tabindex="-1">3. Security &amp; Collaboration Invariants <a class="header-anchor" href="#_3-security-collaboration-invariants" aria-label="Permalink to &quot;3. Security &amp; Collaboration Invariants&quot;">​</a></h2><ol><li>Tenant repository binaries encrypted via <code>RepositoryEnvelopeCrypto</code> use per-object DEKs wrapped by AWS KMS/master keys; <code>Admin</code> accounts are explicitly blocked from decrypting workspace/client vault media.</li><li>Approval state transitions preserve audit trails (<code>BR-35</code>) and enforce <code>Manager</code> internal review before <code>Client</code> sign-off when two-tier approval is configured.</li></ol>',12)])])}const f=t(l,[["render",c]]);export{u as __pageData,f as default};
